'use client';
import {useEffect, useState} from 'react';
import {Building2, Check, Loader2} from 'lucide-react';

export type Account = {id: string; name: string; email: string; role: 'superuser' | 'office' | 'finance' | 'field'; mustChangePassword?: boolean};
type OrgUser = Account & {active: number; mustChangePassword?: number};

const roleLabel = (role: string) => role === 'superuser' ? 'Super user' : role === 'finance' ? 'Finance officer' : role === 'field' ? 'Field officer' : 'Registration / compliance';

function fieldValue(form: HTMLFormElement, name: string) {
  const field = form.elements.namedItem(name);
  return field && 'value' in field ? String(field.value) : '';
}

export function LoginScreen({onSuccess, setupRequired = false, setupTokenRequired = false}: {onSuccess: (user: Account) => void; setupRequired?: boolean; setupTokenRequired?: boolean}) {
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  return (
    <div className="login-screen">
      <section className="login-card">
        <div className="brand"><div className="brand-mark"><Building2 size={26} /></div><div>Sol Plaatje<span>MUNICIPALITY</span></div></div>
        <p className="eyebrow">LOCAL ECONOMIC DEVELOPMENT</p>
        <h1>{setupRequired ? 'Create the administrator' : 'Sign in to the vendor register'}</h1>
        <p className="subtitle">{setupRequired ? 'This register has no users yet. Create the super user once. The password is not shown again.' : 'Office staff and the super user sign in here. Field officers sign in on the field visits app.'}</p>
        <form onSubmit={async event => {
          event.preventDefault();
          const form = event.currentTarget;
          const name = fieldValue(form, 'name').trim();
          const email = fieldValue(form, 'email').trim();
          const password = fieldValue(form, 'password');
          const confirm = fieldValue(form, 'confirm');
          const setupToken = fieldValue(form, 'setupToken');
          setBusy(true);
          setError('');
          try {
            if (setupRequired && password !== confirm) throw new Error('Enter the same password twice.');
            const response = await fetch('/api/auth', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(setupRequired ? {action: 'setup', name, email, password, setupToken} : {action: 'login', email, password})});
            const body: any = await response.json();
            if (!response.ok) throw new Error(body.error || 'Sign-in failed');
            onSuccess(body.user);
          } catch (cause) {
            setError(cause instanceof Error ? cause.message : 'Sign-in failed');
          } finally {
            setBusy(false);
          }
        }}>
          {error && <div className="field-alert" role="alert">{error}</div>}
          {setupRequired && <label>Full name<input name="name" autoComplete="name" required /></label>}
          {setupRequired && setupTokenRequired && <label>Administrator setup token<input name="setupToken" type="password" autoComplete="off" required minLength={32} /><small>Use the one-time setup token supplied by the system owner.</small></label>}
          <label>Email address<input name="email" type="email" autoComplete="username" required /></label>
          <label>Password<input name="password" type="password" autoComplete={setupRequired ? 'new-password' : 'current-password'} required minLength={setupRequired ? 12 : 8} /></label>
          {setupRequired && <label>Confirm password<input name="confirm" type="password" autoComplete="new-password" required minLength={12} /></label>}
          <button className="primary" disabled={busy} type="submit">{busy ? <Loader2 size={17} className="spin" /> : <Check size={17} />}{setupRequired ? 'Create administrator' : 'Sign in'}</button>
        </form>
      </section>
    </div>
  );
}

export function ChangePasswordScreen({onSuccess, onSignOut}: {onSuccess: (user: Account) => void; onSignOut: () => void}) {
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  return (
    <div className="login-screen">
      <section className="login-card">
        <div className="brand"><div className="brand-mark"><Building2 size={26} /></div><div>Sol Plaatje<span>MUNICIPALITY</span></div></div>
        <p className="eyebrow">LOCAL ECONOMIC DEVELOPMENT</p>
        <h1>Choose a new password</h1>
        <p className="subtitle">This account cannot open the register until the password is replaced. Use a different password of at least 8 characters. Other devices signed in with the previous password are signed out.</p>
        <form onSubmit={async event => {
          event.preventDefault();
          const form = event.currentTarget;
          const currentPassword = fieldValue(form, 'currentPassword');
          const password = fieldValue(form, 'password');
          const confirm = fieldValue(form, 'confirm');
          setError('');
          if (password !== confirm) {
            setError('Enter the same new password twice.');
            return;
          }
          setBusy(true);
          try {
            const response = await fetch('/api/auth', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({action: 'change-password', currentPassword, password})});
            const body: any = await response.json();
            if (!response.ok) throw new Error(body.error || 'Could not change the password');
            onSuccess(body.user);
          } catch (cause) {
            setError(cause instanceof Error ? cause.message : 'Could not change the password');
          } finally {
            setBusy(false);
          }
        }}>
          {error && <div className="field-alert" role="alert">{error}</div>}
          <label>Current password<input name="currentPassword" type="password" autoComplete="current-password" required /></label>
          <label>New password<input name="password" type="password" autoComplete="new-password" required minLength={8} /></label>
          <label>Confirm new password<input name="confirm" type="password" autoComplete="new-password" required minLength={8} /></label>
          <button className="primary" disabled={busy} type="submit">{busy ? <Loader2 size={17} className="spin" /> : <Check size={17} />}Save password</button>
        </form>
        <button className="text-button" type="button" onClick={onSignOut}>Sign out</button>
      </section>
    </div>
  );
}

export function UsersScreen() {
  const [users, setUsers] = useState<OrgUser[]>([]);
  const [draft, setDraft] = useState({id: '', name: '', email: '', role: 'office', password: '', active: true});
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [busy, setBusy] = useState(false);
  async function load() {
    const response = await fetch('/api/auth', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({action: 'users'})});
    const body: any = await response.json();
    if (!response.ok) throw new Error(body.error || 'Could not load users');
    setUsers(body.users);
  }
  useEffect(() => {
    const controller = new AbortController();
    fetch('/api/auth', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({action: 'users'}), signal: controller.signal})
      .then(async response => {
        const body: {users: OrgUser[]; error?: string} = await response.json();
        if (!response.ok) throw new Error(body.error || 'Could not load users');
        if (!controller.signal.aborted) setUsers(body.users);
      }).catch(cause => { if (!controller.signal.aborted) setError(cause instanceof Error ? cause.message : 'Could not load users'); });
    return () => controller.abort();
  }, []);
  return (
    <section className="panel">
      <div className="panel-head"><div><h2>Organisation users</h2><p>Super user access, office staff and field officers</p></div></div>
      <form className="user-form" onSubmit={async event => {
        event.preventDefault();
        setBusy(true);
        setError('');
        setNotice('');
        try {
          const response = await fetch('/api/auth', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({action: 'save-user', user: draft})});
          const body: any = await response.json();
          if (!response.ok) throw new Error(body.error || 'Could not save this user');
          setDraft({id: '', name: '', email: '', role: 'office', password: '', active: true});
          setNotice(draft.id ? 'User updated.' : 'User added.');
          await load();
        } catch (cause) {
          setError(cause instanceof Error ? cause.message : 'Could not save this user');
        } finally {
          setBusy(false);
        }
      }}>
        {error && <div className="field-alert" role="alert">{error}</div>}
        {notice && <div className="field-success" role="status"><Check size={16} />{notice}</div>}
        <div className="form-grid">
          <label>Full name<input value={draft.name} onChange={event => setDraft({...draft, name: event.target.value})} required /></label>
          <label>Email address<input type="email" value={draft.email} onChange={event => setDraft({...draft, email: event.target.value})} required /></label>
          <label>Role<select value={draft.role} onChange={event => setDraft({...draft, role: event.target.value})}><option value="office">Registration / compliance</option><option value="finance">Finance officer</option><option value="field">Field officer</option><option value="superuser">Super user</option></select></label>
          <label>{draft.id ? 'New password (optional)' : 'Temporary password'}<input type="password" autoComplete="new-password" value={draft.password} onChange={event => setDraft({...draft, password: event.target.value})} required={!draft.id} minLength={draft.password ? 8 : undefined} /></label>
        </div>
        <label className="check-line"><input type="checkbox" checked={draft.active} onChange={event => setDraft({...draft, active: event.target.checked})} />Account can sign in</label>
        <p className="hint">A password set for someone else is temporary. They must replace it the next time they sign in. There is no email reset: set a new temporary password here if they are locked out.</p>
        <div className="modal-foot user-form-actions"><button className="secondary" type="button" onClick={() => setDraft({id: '', name: '', email: '', role: 'office', password: '', active: true})}>Clear</button><button className="primary" disabled={busy} type="submit">{busy ? <Loader2 size={16} className="spin" /> : <Check size={16} />}{draft.id ? 'Save user' : 'Add user'}</button></div>
      </form>
      <div className="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Access</th><th></th></tr></thead><tbody>
        {users.map(user => <tr key={user.id}><td><strong>{user.name}</strong></td><td>{user.email}</td><td>{roleLabel(user.role)}</td><td>{user.active ? (user.mustChangePassword ? 'Must change password' : 'Active') : 'Disabled'}</td><td><button className="text-button" type="button" onClick={() => { setDraft({id: user.id, name: user.name, email: user.email, role: user.role, password: '', active: !!user.active}); setNotice(''); setError(''); }}>Edit</button><button className="text-button" type="button" onClick={async () => { setError(''); setNotice(''); try { const response = await fetch('/api/auth', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({action: 'revoke-sessions', userId: user.id})}); const body: any = await response.json(); if (!response.ok) throw new Error(body.error || 'Could not sign out devices'); setNotice('Signed out devices for ' + user.name + '.'); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Could not sign out devices'); } }}>Sign out devices</button></td></tr>)}
      </tbody></table></div>
    </section>
  );
}

import {database, bootstrapToken} from '../../../lib/server';
import {checkPassword, clearOtherSessions, clearSessions, clientIp, ensureAccounts, hashPassword, isLocalHost, openSession, passwordPending, publicAccount, requestIsSecure, sessionCookie, sessionToken, sessionUser} from '../../../lib/accounts';
import {fieldCorsHeaders, withFieldCors, mutationOriginError} from '../../../lib/cors';

const roles = ['superuser', 'office', 'finance', 'field'];
const WINDOW_MS = 15 * 60 * 1000;

function json(body: unknown, status = 200, extra?: HeadersInit) {
  const headers = new Headers(extra);
  if (!headers.has('Cache-Control')) headers.set('Cache-Control', 'no-store');
  return Response.json(body, {status, headers});
}

function deviceLabel(req: Request) {
  return (req.headers.get('user-agent') || 'Unknown device').slice(0, 160);
}

function friendlyDevice(value: string) {
  const platform = /iPhone/i.test(value) ? 'iPhone' : /iPad/i.test(value) ? 'iPad' : /Android/i.test(value) ? 'Android device' : /Windows/i.test(value) ? 'Windows computer' : /Macintosh|Mac OS/i.test(value) ? 'Mac' : /Linux/i.test(value) ? 'Linux computer' : 'Unknown device';
  const browser = /Edg\//i.test(value) ? 'Microsoft Edge' : /CriOS|Chrome\//i.test(value) ? 'Google Chrome' : /Firefox\//i.test(value) ? 'Firefox' : /Safari\//i.test(value) ? 'Safari' : /wv\)/i.test(value) ? 'App web view' : '';
  return browser ? `${platform} · ${browser}` : platform;
}

async function publicSessionId(token: string) {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(token));
  return [...new Uint8Array(digest)].slice(0, 12).map(byte => byte.toString(16).padStart(2, '0')).join('');
}

function secureCookie(req: Request, token: string, maxAge: number) {
  return sessionCookie(token, maxAge, requestIsSecure(req));
}

function cleartextBlocked(req: Request) {
  return !requestIsSecure(req) && !isLocalHost(new URL(req.url).hostname);
}

function validEmail(email: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

async function userCount(db: ReturnType<typeof database>) {
  const row = await db.prepare('SELECT COUNT(*) AS n FROM users').first<{n: number}>();
  return Number(row?.n || 0);
}

async function setupRequired(db: ReturnType<typeof database>) {
  return (await userCount(db)) === 0;
}

async function tooManyAttempts(db: ReturnType<typeof database>, email: string, ip: string) {
  const since = new Date(Date.now() - WINDOW_MS).toISOString();
  const byEmail = email ? await db.prepare('SELECT COUNT(*) AS n FROM login_attempts WHERE email=? AND created_at>?').bind(email, since).first<{n: number}>() : null;
  if (Number(byEmail?.n || 0) >= 5) return true;
  const byIp = await db.prepare('SELECT COUNT(*) AS n FROM login_attempts WHERE ip=? AND created_at>?').bind(ip, since).first<{n: number}>();
  return Number(byIp?.n || 0) >= 30;
}

async function recordAttempt(db: ReturnType<typeof database>, email: string, ip: string) {
  await db.prepare('INSERT INTO login_attempts(id,email,ip,created_at) VALUES(?,?,?,?)').bind(crypto.randomUUID(), email || '-', ip, new Date().toISOString()).run();
}

async function handleGet(req: Request) {
  const db = database();
  await ensureAccounts(db);
  const account = await sessionUser(db, req);
  if (!account) return json({user: null, setupRequired: await setupRequired(db), setupTokenRequired: !isLocalHost(new URL(req.url).hostname)});
  return json({user: publicAccount(account)});
}

async function handleSetup(req: Request, db: ReturnType<typeof database>, body: any) {
  const rejected = mutationOriginError(req);
  if (rejected) return rejected;
  if (cleartextBlocked(req)) return json({error: 'Administrator setup requires a secure https connection.'}, 400);
  if (!(await setupRequired(db))) return json({error: 'An administrator already exists. Sign in instead.'}, 409);
  if (!isLocalHost(new URL(req.url).hostname)) {
    const expected = bootstrapToken();
    if (expected.length < 32) return json({error: 'The system owner must configure a BOOTSTRAP_TOKEN of at least 32 characters before administrator setup.'}, 503);
    if (typeof body.setupToken !== 'string' || body.setupToken !== expected) return json({error: 'The administrator setup token is not correct.'}, 403);
  }
  const name = String(body.name || '').trim().replace(/\s+/g, ' ');
  const email = String(body.email || '').trim().toLowerCase();
  const password = String(body.password || '');
  if (name.length < 2 || name.length > 80) return json({error: 'Enter the administrator’s name.'}, 400);
  if (!validEmail(email)) return json({error: 'Enter a valid email address.'}, 400);
  if (password.length < 12) return json({error: 'Choose a password of at least 12 characters.'}, 400);
  if (password.toLowerCase() === email) return json({error: 'Do not use the email address as the password.'}, 400);
  if (await userCount(db)) return json({error: 'An administrator already exists. Sign in instead.'}, 409);
  // Never remove this claim on incoming setup requests: deleting it permitted
  // concurrent clients to race to become the first superuser.
  const claim = await db.prepare("INSERT OR IGNORE INTO app_meta(key,value) VALUES('administrator',?)")
    .bind(new Date().toISOString()).run();
  if (!claim.meta?.changes) return json({error: 'Administrator setup was already claimed. Contact the system administrator if initial setup failed.'}, 409);
  const id = crypto.randomUUID();
  await db.prepare('INSERT INTO users(id,name,email,password_hash,role,active,created_at,must_change_password) VALUES(?,?,?,?,?,?,?,0)')
    .bind(id, name, email, await hashPassword(password), 'superuser', 1, new Date().toISOString()).run();
  const session = await openSession(db, id, deviceLabel(req));
  return json({user: publicAccount({id, name, email, role: 'superuser', active: 1, mustChangePassword: 0}), token: session.token}, 200, {'Set-Cookie': secureCookie(req, session.token, session.maxAge)});
}

async function handlePost(req: Request) {
  const db = database();
  await ensureAccounts(db);
  const origin = req.headers.get('origin');
  if (origin && origin !== new URL(req.url).origin && !fieldCorsHeaders(req)) {
    return json({error: 'Invalid request origin.'}, 403);
  }
  let body: any;
  try {
    body = await req.json();
  } catch {
    return json({error: 'Sign-in details could not be read. Try again.'}, 400);
  }
  if (body.action === 'setup') return handleSetup(req, db, body);
  if (body.action === 'login') {
    if (cleartextBlocked(req)) return json({error: 'Sign in requires a secure https connection.'}, 400);
    const email = String(body.email || '').trim().toLowerCase();
    const password = String(body.password || '');
    const ip = clientIp(req);
    if (await tooManyAttempts(db, email, ip)) return json({error: 'Too many sign-in attempts. Try again in 15 minutes.'}, 429);
    const row = await db.prepare('SELECT id,name,email,role,active,password_hash,must_change_password AS mustChangePassword FROM users WHERE email=?').bind(email).first<any>();
    const valid = await checkPassword(password, row?.active ? row.password_hash : undefined);
    if (!row || !row.active || !valid) {
      await recordAttempt(db, email, ip);
      return json({error: 'The email or password is not correct.'}, 401);
    }
    await db.prepare('DELETE FROM login_attempts WHERE email=?').bind(email).run();
    const session = await openSession(db, row.id, deviceLabel(req));
    const account = {id: row.id, name: row.name, email: row.email, role: row.role, active: row.active, mustChangePassword: row.mustChangePassword};
    return json({user: publicAccount(account), token: session.token}, 200, {'Set-Cookie': secureCookie(req, session.token, session.maxAge)});
  }
  const rejected = mutationOriginError(req, true);
  if (rejected) return rejected;
  const account = await sessionUser(db, req);
  if (!account) return json({error: 'Sign in required.'}, 401);
  if (body.action === 'logout') {
    const token = sessionToken(req);
    if (token) await db.prepare('DELETE FROM sessions WHERE token=?').bind(token).run();
    return json({ok: true}, 200, {'Set-Cookie': sessionCookie('', 0, requestIsSecure(req))});
  }
  if (body.action === 'change-password') {
    const current = String(body.currentPassword || '');
    const next = String(body.password || '');
    if (next.length < 8) return json({error: 'Choose a password of at least 8 characters.'}, 400);
    if (next === current) return json({error: 'Choose a different password.'}, 400);
    if (next.toLowerCase() === account.email) return json({error: 'Do not use the email address as the password.'}, 400);
    const row = await db.prepare('SELECT password_hash FROM users WHERE id=?').bind(account.id).first<{password_hash: string}>();
    if (!(await checkPassword(current, row?.password_hash))) return json({error: 'The current password is not correct.'}, 401);
    await db.prepare('UPDATE users SET password_hash=?, must_change_password=0 WHERE id=?').bind(await hashPassword(next), account.id).run();
    await clearOtherSessions(db, account.id, sessionToken(req));
    return json({user: publicAccount({...account, mustChangePassword: 0})});
  }
  if (passwordPending(account)) return json({error: 'Change your password before continuing.'}, 403);
  if (body.action === 'sessions') {
    const userId = account.role === 'superuser' ? String(body.userId || account.id) : account.id;
    const rows = await db.prepare('SELECT token,created_at AS createdAt,expires_at AS expiresAt,device FROM sessions WHERE user_id=? AND expires_at>? ORDER BY created_at DESC').bind(userId, new Date().toISOString()).all<any>();
    const current = sessionToken(req);
    return json({sessions: await Promise.all(rows.results.map(async row => ({id: await publicSessionId(row.token), createdAt: row.createdAt, expiresAt: row.expiresAt, device: friendlyDevice(row.device || ''), current: row.token === current})))});
  }
  if (body.action === 'revoke-session') {
    const target = account.role === 'superuser' ? String(body.userId || account.id) : account.id;
    const requested = String(body.sessionId || '');
    const rows = await db.prepare('SELECT token FROM sessions WHERE user_id=?').bind(target).all<{token: string}>();
    let token = '';
    for (const row of rows.results) if (await publicSessionId(row.token) === requested) { token = row.token; break; }
    if (!token) return json({error: 'That device session is no longer active.'}, 404);
    if (token === sessionToken(req)) return json({error: 'Use Sign out to end the session on this device.'}, 400);
    await db.prepare('DELETE FROM sessions WHERE token=? AND user_id=?').bind(token, target).run();
    return json({ok: true});
  }
  if (body.action === 'revoke-sessions') {
    const target = String(body.userId || account.id);
    if (account.role !== 'superuser' && target !== account.id) return json({error: 'You can only sign out your own other devices.'}, 403);
    const exists = await db.prepare('SELECT id FROM users WHERE id=?').bind(target).first();
    if (!exists) return json({error: 'User no longer exists.'}, 404);
    if (target === account.id) await clearOtherSessions(db, target, sessionToken(req));
    else await clearSessions(db, target);
    return json({ok: true});
  }
  if (account.role !== 'superuser') return json({error: 'Only the super user can manage accounts.'}, 403);
  if (body.action === 'users') {
    const rows = await db.prepare('SELECT id,name,email,role,active,must_change_password AS mustChangePassword,created_at AS createdAt FROM users ORDER BY created_at').all<any>();
    return json({users: rows.results});
  }
  if (body.action === 'save-user') {
    const input = body.user || {};
    const name = String(input.name || '').trim().replace(/\s+/g, ' ');
    const email = String(input.email || '').trim().toLowerCase();
    const role = String(input.role || '');
    const active = input.active === false || input.active === 0 ? 0 : 1;
    const password = String(input.password || '');
    if (name.length < 2 || name.length > 80) return json({error: 'Enter the person’s name.'}, 400);
    if (!validEmail(email)) return json({error: 'Enter a valid email address.'}, 400);
    if (!roles.includes(role)) return json({error: 'Choose a role.'}, 400);
    const existing = input.id ? await db.prepare('SELECT id,role,active FROM users WHERE id=?').bind(input.id).first<any>() : null;
    if (input.id && !existing) return json({error: 'User no longer exists.'}, 404);
    const duplicate = await db.prepare('SELECT id FROM users WHERE email=? AND id<>?').bind(email, existing?.id || '').first<any>();
    if (duplicate) return json({error: 'That email address is already in use.'}, 409);
    if (!existing && password.length < 8) return json({error: 'Set a password of at least 8 characters.'}, 400);
    if (password && (password.length < 8 || password.toLowerCase() === email)) return json({error: 'Set a password of at least 8 characters that is not the email address.'}, 400);
    if (existing?.role === 'superuser' && (role !== 'superuser' || !active)) {
      const others = await db.prepare("SELECT COUNT(*) AS n FROM users WHERE role='superuser' AND active=1 AND id<>?").bind(existing.id).first<any>();
      if (!others?.n) return json({error: 'Keep at least one active super user.'}, 400);
    }
    const now = new Date().toISOString();
    if (!existing) {
      await db.prepare('INSERT INTO users(id,name,email,password_hash,role,active,created_at,must_change_password) VALUES(?,?,?,?,?,?,?,1)')
        .bind(crypto.randomUUID(), name, email, await hashPassword(password), role, active, now).run();
      return json({ok: true});
    }
    if (password) {
      const own = existing.id === account.id;
      await db.prepare('UPDATE users SET name=?,email=?,role=?,active=?,password_hash=?,must_change_password=? WHERE id=?').bind(name, email, role, active, await hashPassword(password), own ? 0 : 1, existing.id).run();
      if (own) await clearOtherSessions(db, existing.id, sessionToken(req));
      else await clearSessions(db, existing.id);
    } else {
      await db.prepare('UPDATE users SET name=?,email=?,role=?,active=? WHERE id=?').bind(name, email, role, active, existing.id).run();
      if (!active) await clearSessions(db, existing.id);
    }
    return json({ok: true});
  }
  return json({error: 'Unknown action'}, 400);
}

export function OPTIONS(req: Request) {
  const headers = fieldCorsHeaders(req);
  if (!headers) return new Response(null, {status: 403});
  return new Response(null, {status: 204, headers});
}

export function GET(req: Request) {
  return handleGet(req).then(res => withFieldCors(req, res)).catch(error => {
    console.error(error);
    return withFieldCors(req, json({error: 'Sign-in is unavailable. Please try again.'}, 503));
  });
}

export function POST(req: Request) {
  return handlePost(req).then(res => withFieldCors(req, res)).catch(error => {
    console.error(error);
    return withFieldCors(req, json({error: 'Sign-in is unavailable. Please try again.'}, 503));
  });
}

import {bucket, database} from '../../../lib/server';
import {ensureAccounts, passwordPending, sessionUser} from '../../../lib/accounts';
import {buildSnapshot, restoreSnapshot, verifySnapshot} from '../../../lib/backup';
import {writeAudit} from '../../../lib/workflows';
import {mutationOriginError} from '../../../lib/cors';

function json(body: unknown, status = 200, extra?: HeadersInit) {
  const headers = new Headers(extra);
  headers.set('Cache-Control', 'no-store');
  return Response.json(body, {status, headers});
}

async function superUser(req: Request) {
  const db = database();
  await ensureAccounts(db);
  const account = await sessionUser(db, req);
  if (!account) return json({error: 'Sign in required.'}, 401);
  if (passwordPending(account)) return json({error: 'Change your password before continuing.'}, 403);
  if (account.role !== 'superuser') return json({error: 'Only the super user can export, verify or restore a register backup.'}, 403);
  return {db, account};
}

export async function GET(req: Request) {
  try {
    const viewer = await superUser(req);
    if (viewer instanceof Response) return viewer;
    const stamp = new Date().toISOString();
    const snapshot = await buildSnapshot(viewer.db, bucket(), viewer.account.name, stamp);
    // A backup is a read of everything: record that it happened.
    await writeAudit(viewer.db, 'backup', stamp, 'exported', null, {manifest: snapshot.manifest, checksum: snapshot.checksum}, viewer.account.name, stamp);
    const filename = `vendor-register-backup-${stamp.slice(0, 19).replace(/[:T]/g, '-')}.json`;
    return new Response(JSON.stringify(snapshot, null, 2), {
      headers: {
        'Content-Type': 'application/json',
        'Content-Disposition': `attachment; filename="${filename}"`,
        'Cache-Control': 'no-store',
        'X-Backup-Checksum': snapshot.checksum,
        'X-Backup-Rows': String(Object.values(snapshot.manifest).reduce((total, count) => total + count, 0)),
      },
    });
  } catch (error) {
    console.error(error);
    return json({error: 'The backup could not be prepared.'}, 503);
  }
}

export async function POST(req: Request) {
  const rejected = mutationOriginError(req);
  if (rejected) return rejected;
  try {
    const viewer = await superUser(req);
    if (viewer instanceof Response) return viewer;
    const body: any = await req.json().catch(() => null);
    if (!body || !['verify', 'restore'].includes(body.action)) return json({error: 'Unknown action.'}, 400);
    const document = body.document;
    if (!document || typeof document !== 'object') return json({error: 'Attach the exported backup document to verify.'}, 400);
    const result = await verifySnapshot(document);
    const stamp = new Date().toISOString();
    if (body.action === 'verify') {
      await writeAudit(viewer.db, 'backup', document.generatedAt || stamp, 'verified', null, {ok: result.ok, counts: result.counts}, viewer.account.name, stamp, viewer.account.id);
      return json(result);
    }
    if (!result.restorable) return json({error: 'Only a verified version 2 backup can be restored.', ...result}, 400);
    if (String(body.confirmation || '') !== result.confirmation) return json({error: `Type ${result.confirmation} to confirm this restore.`}, 400);
    const restored = await restoreSnapshot(viewer.db, bucket(), document);
    await writeAudit(viewer.db, 'backup', document.generatedAt || stamp, 'restored', null, {checksum: restored.checksum, counts: restored.counts, objects: restored.objects}, viewer.account.name, stamp, viewer.account.id);
    return json({ok: true, ...restored});
  } catch (error) {
    return json({error: error instanceof Error ? error.message : 'The backup could not be verified.'}, 400);
  }
}

import {database, noticeWebhook} from '../../../lib/server';
import {ensureAccounts, passwordPending, sessionUser} from '../../../lib/accounts';
import {fieldCorsHeaders, withFieldCors, mutationOriginError} from '../../../lib/cors';
import {noticePdf, noticeText, noticeVendor} from '../../../lib/notices';
import {submissionKey} from '../../../lib/submissions';
import {Vendor, Entry} from '../../../lib/data';
import {can} from '../../../lib/capabilities';

const handovers = ['draft', 'handover', 'acknowledged'];

function json(body: unknown, status = 200) {
  return Response.json(body, {status, headers: {'Cache-Control': 'no-store'}});
}

async function viewer(req: Request) {
  const db = database();
  await ensureAccounts(db);
  const account = await sessionUser(db, req);
  if (!account) return json({error: 'Sign in required.'}, 401);
  if (passwordPending(account)) return json({error: 'Change your password before continuing.'}, 403);
  return account;
}

async function noticeCase(db: ReturnType<typeof database>, eventId: string) {
  const event = await db.prepare('SELECT id,vendor_id,kind,amount,note,due,created_at,actor,resolved,snapshot FROM events WHERE id=?').bind(eventId).first<any>();
  if (!event || !['Warning', 'Violation'].includes(event.kind)) return null;
  const row = await db.prepare('SELECT payload FROM vendors WHERE id=?').bind(event.vendor_id).first<{payload: string}>();
  if (!row) return null;
  const vendor = JSON.parse(row.payload) as Vendor;
  const entry: Entry = {id: event.id, vendorId: event.vendor_id, kind: event.kind, amount: event.amount, note: event.note, due: event.due, createdAt: event.created_at, actor: event.actor, resolved: event.resolved, snapshot: event.snapshot || ''};
  return {vendor: noticeVendor(vendor, entry), entry};
}

async function record(db: ReturnType<typeof database>, eventId: string, method: string, status: string, detail: string, actor: string, key = '', recipient = '') {
  const once = ['handover', 'acknowledged', 'escalated', 'municipal'];
  if (once.includes(method)) {
    const existing = await db.prepare('SELECT id,status FROM notice_deliveries WHERE event_id=? AND method=? ORDER BY created_at DESC').bind(eventId, method).first<{id: string; status: string}>();
    if (existing && !(method === 'municipal' && ['failed', 'rejected'].includes(existing.status))) return existing.id;
  }
  if (key) {
    const byKey = await db.prepare('SELECT id FROM notice_deliveries WHERE event_id=? AND idempotency_key=?').bind(eventId, key).first<{id: string}>();
    if (byKey) return byKey.id;
  }
  const id = crypto.randomUUID();
  await db.prepare('INSERT INTO notice_deliveries(id,event_id,method,status,detail,actor,created_at,recipient,idempotency_key) VALUES(?,?,?,?,?,?,?,?,?)')
    .bind(id, eventId, method, status, detail.slice(0, 300), actor, new Date().toISOString(), recipient.slice(0, 160), key).run();
  return id;
}

function webhookAllowed(value: string) {
  try {
    const url = new URL(value);
    if (url.protocol === 'https:') return true;
    return url.protocol === 'http:' && ['localhost', '127.0.0.1', '::1'].includes(url.hostname);
  } catch {
    return false;
  }
}

async function handleGet(req: Request) {
  const account = await viewer(req);
  if (account instanceof Response) return account;
  const eventId = new URL(req.url).searchParams.get('eventId') || '';
  const found = await noticeCase(database(), eventId);
  if (!found) return json({error: 'Notice not found.'}, 404);
  const text = noticeText(found.vendor, found.entry);
  await record(database(), eventId, 'pdf', 'downloaded', 'PDF downloaded by an official', account.name);
  const pdf = noticePdf(text.split('\n'));
  return new Response(pdf, {headers: {'Content-Type': 'application/pdf', 'Content-Disposition': `attachment; filename="notice-${eventId.slice(0, 8)}.pdf"`, 'Cache-Control': 'private, no-store', 'X-Content-Type-Options': 'nosniff'}});
}

async function handlePost(req: Request) {
  const rejected = mutationOriginError(req, true);
  if (rejected) return rejected;
  const account = await viewer(req);
  if (account instanceof Response) return account;
  if (!can(account.role, 'compliance.write')) return json({error: 'Your role cannot change notice delivery or compliance cases.'}, 403);
  const body: any = await req.json();
  const eventId = String(body.eventId || '');
  const found = await noticeCase(database(), eventId);
  if (!found) return json({error: 'Notice not found.'}, 404);
  const db = database();
  const key = body.idempotencyKey ? submissionKey(body.idempotencyKey) : '';
  if (body.action === 'deliver') {
    const method = String(body.method || '');
    if (!handovers.includes(method)) return json({error: 'Choose a delivery record.'}, 400);
    const status = method === 'draft' ? 'draft opened' : method === 'handover' ? 'handed to trader' : 'trader acknowledged';
    await record(db, eventId, method, status, status, account.name, key, method === 'handover' ? 'trader' : '');
    return json({ok: true, message: method === 'draft' ? 'Draft opened. This is not a delivery confirmation.' : 'Delivery record saved.'});
  }
  if (body.action === 'send') {
    const webhook = noticeWebhook();
    if (!webhook || !webhookAllowed(webhook)) return json({error: 'Municipal email is not connected. Download the PDF or use the email draft.', status: 'not connected'}, 409);
    const claimTtlMs = 120000;
    const staleBefore = new Date(Date.now() - claimTtlMs).toISOString();
    await db.prepare("UPDATE notice_deliveries SET status='failed', detail='Send claim expired before the sender responded' WHERE method='municipal' AND status='sending' AND created_at<?").bind(staleBefore).run();
    const latest = await db.prepare("SELECT id,status,detail,created_at AS createdAt FROM notice_deliveries WHERE event_id=? AND method='municipal' ORDER BY created_at DESC").bind(eventId).first<{id: string; status: string; detail: string; createdAt: string}>();
    if (latest?.status === 'accepted by sender') return json({ok: true, duplicate: true, status: latest.status, message: 'The municipal sender already accepted this notice.'});
    if (latest?.status === 'sending') return json({ok: true, duplicate: true, status: 'sending', message: 'A municipal send is already in progress.'});
    const claimId = crypto.randomUUID();
    try {
      await db.prepare('INSERT INTO notice_deliveries(id,event_id,method,status,detail,actor,created_at,recipient,idempotency_key) VALUES(?,?,?,?,?,?,?,?,?)')
        .bind(claimId, eventId, 'municipal', 'sending', 'Claimed before the sender is called', account.name, new Date().toISOString(), found.vendor.email.slice(0, 160), key).run();
    } catch (error) {
      if (!/UNIQUE/i.test(String(error))) throw error;
      const current = await db.prepare("SELECT status FROM notice_deliveries WHERE event_id=? AND method='municipal' AND status IN ('sending','accepted by sender') ORDER BY created_at DESC").bind(eventId).first<{status: string}>();
      return json({ok: true, duplicate: true, status: current?.status || 'sending', message: 'Another request already claimed this municipal send.'});
    }
    const payload = {reference: found.entry.id, idempotencyKey: found.entry.id, kind: found.entry.kind, vendorId: found.vendor.id, vendorName: found.vendor.name, business: found.vendor.business, email: found.vendor.email, text: noticeText(found.vendor, found.entry)};
    try {
      const response = await fetch(webhook, {method: 'POST', headers: {'Content-Type': 'application/json', 'Idempotency-Key': found.entry.id}, body: JSON.stringify(payload), signal: AbortSignal.timeout(20000)});
      if (!response.ok) {
        await db.prepare('UPDATE notice_deliveries SET status=?,detail=? WHERE id=?').bind('rejected', 'HTTP ' + response.status, claimId).run();
        return json({error: 'The municipal notice service did not accept this notice.', status: 'rejected'}, 502);
      }
      await db.prepare('UPDATE notice_deliveries SET status=?,detail=? WHERE id=?').bind('accepted by sender', 'HTTP ' + response.status, claimId).run();
      return json({ok: true, status: 'accepted by sender', message: 'The municipal sender accepted the notice. This confirms acceptance, not that the trader opened it.'});
    } catch (error) {
      console.error(error);
      const timedOut = error instanceof Error && (/abort|timeout/i.test(error.name + error.message));
      await db.prepare('UPDATE notice_deliveries SET status=?,detail=? WHERE id=?').bind('failed', timedOut ? 'The municipal sender timed out' : 'The municipal sender could not be reached', claimId).run();
      return json({error: timedOut ? 'The municipal sender timed out. Retry when ready.' : 'The municipal sender could not be reached. The email draft is still available.', status: 'failed'}, 502);
    }
  }
  if (body.action === 'escalate') {
    const note = String(body.note || '').trim();
    if (note.length < 3 || note.length > 1000) return json({error: 'Enter why this case is being escalated.'}, 400);
    if (found.entry.resolved) return json({error: 'This case is already resolved.'}, 409);
    const existing = await db.prepare("SELECT id FROM notice_deliveries WHERE event_id=? AND method='escalated'").bind(eventId).first();
    if (existing) return json({ok: true, duplicate: true, message: 'Escalation already recorded.'});
    const id = crypto.randomUUID();
    const now = new Date().toISOString();
    await db.batch([
      db.prepare('INSERT INTO events(id,vendor_id,kind,amount,note,due,created_at,actor,resolved) VALUES(?,?,?,?,?,?,?,?,0)').bind(id, found.vendor.id, 'Escalation', 0, 'Case ' + found.entry.id + ': ' + note, found.entry.due || '', now, account.name),
      db.prepare("UPDATE events SET case_status='escalated' WHERE id=? AND resolved=0").bind(eventId),
      db.prepare('INSERT INTO notice_deliveries(id,event_id,method,status,detail,actor,created_at,recipient,idempotency_key) VALUES(?,?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(), eventId, 'escalated', 'recorded', note.slice(0, 300), account.name, now, String(body.destination || 'LED Office').slice(0, 160), key),
    ]);
    return json({ok: true, message: 'Escalation recorded.'});
  }
  return json({error: 'Unknown action'}, 400);
}

export function OPTIONS(req: Request) {
  const headers = fieldCorsHeaders(req);
  if (!headers) return new Response(null, {status: 403});
  return new Response(null, {status: 204, headers});
}

export function GET(req: Request) {
  return handleGet(req).then(res => withFieldCors(req, res)).catch(error => {
    console.error(error);
    return withFieldCors(req, json({error: 'The notice could not be prepared.'}, 503));
  });
}

export function POST(req: Request) {
  return handlePost(req).then(res => withFieldCors(req, res)).catch(error => {
    console.error(error);
    return withFieldCors(req, json({error: 'The notice record could not be saved.'}, 503));
  });
}

import {mutationOriginError} from '../../../lib/cors';
import {database} from '../../../lib/server';
import {ensureAccounts, passwordPending, sessionUser} from '../../../lib/accounts';
import {can} from '../../../lib/capabilities';
import {noticePdf} from '../../../lib/notices';
import {Vendor} from '../../../lib/data';
import {writeAudit} from '../../../lib/workflows';

function json(body: unknown, status = 200) {
  return Response.json(body, {status, headers: {'Cache-Control': 'no-store'}});
}

function stamp() {
  return new Date().toISOString();
}

/**
 * Permit certificate. Printing one is recorded as a permit document, so the
 * office can see when a certificate was produced and for which expiry date.
 */
export async function GET(req: Request) {
  try {
    const db = database();
    await ensureAccounts(db);
    const account = await sessionUser(db, req);
    if (!account) return json({error: 'Sign in required.'}, 401);
    if (passwordPending(account)) return json({error: 'Change your password before continuing.'}, 403);
    if (!can(account.role, 'permits.write') && account.role !== 'field') return json({error: 'Your role cannot produce permit certificates.'}, 403);

    const params = new URL(req.url).searchParams;
    const vendorId = String(params.get('vendorId') || '');
    const record = params.get('record') !== 'no';
    const row = await db.prepare('SELECT payload FROM vendors WHERE id=? COLLATE NOCASE').bind(vendorId).first<{payload: string}>();
    if (!row) return json({error: 'Vendor not found.'}, 404);
    const vendor = JSON.parse(row.payload) as Vendor;

    const permits = await db.prepare("SELECT card_serial AS cardSerial,status,created_at AS createdAt FROM permits WHERE vendor_id=? ORDER BY created_at").bind(vendor.id).all<any>();
    let currentSerial = '';
    let cardState = 'No card serial is on record.';
    for (const permit of permits.results) {
      if (permit.status === 'revoked') currentSerial = '';
      else if ((permit.status === 'issued' || permit.status === 'replacement') && permit.cardSerial) currentSerial = String(permit.cardSerial);
    }
    if (currentSerial) cardState = 'Card serial ' + currentSerial;
    if (vendor.status === 'Suspended') cardState += ' — the permit is suspended.';

    const status = vendor.expires && vendor.expires < new Date().toISOString().slice(0, 10) ? 'Expired' : vendor.status;
    if (vendor.sample) return json({error: 'Sample records cannot produce permit certificates.'}, 409);
    if (status !== 'Approved') return json({error: 'Approve the vendor and record a current permit expiry before producing a certificate.'}, 409);
    const lines = [
      'SOL PLAATJE MUNICIPALITY',
      'Local Economic Development Office',
      'TRADING PERMIT CERTIFICATE',
      vendor.sample ? 'SAMPLE — NOT A VALID PERMIT' : '',
      '',
      'Permit holder: ' + vendor.name,
      'Business / trading name: ' + vendor.business,
      'Vendor ID: ' + vendor.id,
      'Trading type: ' + vendor.type,
      'Sector / products: ' + vendor.sector,
      vendor.type === 'Formal'
        ? 'Allocated trading space: ' + vendor.hub + ', unit ' + (vendor.unit || 'not recorded')
        : 'Trading pitch: ' + (vendor.unit || 'not recorded') + (vendor.address ? ' — ' + vendor.address : ''),
      vendor.type === 'Informal' ? 'Recorded coordinates: ' + (vendor.lat || 'not recorded') + ', ' + (vendor.lng || 'not recorded') : '',
      '',
      'Permit issue date: ' + (vendor.issued || 'not recorded'),
      'Permit expiry date: ' + (vendor.expires || 'not recorded'),
      'Permit status at issue: ' + status,
      cardState,
      '',
      'Conditions',
      '1. This permit is valid only at the trading space recorded above.',
      '2. Trading outside the recorded space, or after the expiry date, is not permitted.',
      '3. The permit holder must keep the recorded registration details current.',
      '4. The municipality may inspect the trading space and suspend or revoke this permit after a recorded finding.',
      '',
      'Issued by: ' + account.name,
      'Produced: ' + new Date().toLocaleString('en-ZA', {timeZone: 'Africa/Johannesburg'}),
      'Certificate reference: ' + vendor.id + '-PERMIT-' + (vendor.expires || 'no-expiry'),
      '',
      'This certificate is printed from the vendor register. Confirm the register record on screen before issuing it.',
    ].filter(line => line !== undefined && line !== null);

    if (record) {
      await db.prepare('INSERT INTO permit_documents(id,vendor_id,kind,card_serial,permit_expires,note,actor,actor_id,created_at) VALUES(?,?,?,?,?,?,?,?,?)')
        .bind(crypto.randomUUID(), vendor.id, 'certificate', currentSerial, vendor.expires || '', 'Permit certificate produced', account.name, account.id, stamp()).run();
      await writeAudit(db, 'permit-document', vendor.id, 'certificate produced', null, {cardSerial: currentSerial, expires: vendor.expires || '', status}, account.name, stamp(), account.id);
    }

    return new Response(noticePdf(lines as string[]), {
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `attachment; filename="permit-${vendor.id}.pdf"`,
        'Cache-Control': 'private, no-store',
        'X-Content-Type-Options': 'nosniff',
      },
    });
  } catch (error) {
    console.error(error);
    return json({error: 'The permit certificate could not be prepared.'}, 503);
  }
}

/** Card and permit lifecycle events that are not a permit decision. */
export async function POST(req: Request) {
  const rejected = mutationOriginError(req);
  if (rejected) return rejected;
  try {
    const db = database();
    await ensureAccounts(db);
    const account = await sessionUser(db, req);
    if (!account) return json({error: 'Sign in required.'}, 401);
    if (passwordPending(account)) return json({error: 'Change your password before continuing.'}, 403);
    if (!can(account.role, 'permits.write')) return json({error: 'Your role cannot record card events.'}, 403);
    const body: any = await req.json().catch(() => null);
    if (!body || body.action !== 'card-event') return json({error: 'Unknown action.'}, 400);
    const vendorId = String(body.vendorId || '');
    const kind = String(body.kind || '');
    if (!['printed', 'handed-over', 'reported-lost'].includes(kind)) return json({error: 'Choose a card event.'}, 400);
    const note = String(body.note || '').trim().slice(0, 300);
    if (kind === 'reported-lost' && note.length < 3) return json({error: 'Record how the card was lost or what was reported.'}, 400);
    const vendor = await db.prepare('SELECT id,payload FROM vendors WHERE id=?').bind(vendorId).first<{id: string; payload: string}>();
    if (!vendor) return json({error: 'Vendor not found.'}, 404);
    const profile = JSON.parse(vendor.payload) as Vendor;
    const permits = await db.prepare("SELECT card_serial AS cardSerial,status FROM permits WHERE vendor_id=? ORDER BY created_at").bind(vendorId).all<{cardSerial: string; status: string}>();
    let currentSerial = '';
    for (const permit of permits.results) {
      if (permit.status === 'revoked') currentSerial = '';
      else if (['issued', 'replacement'].includes(permit.status) && permit.cardSerial) currentSerial = permit.cardSerial;
    }
    const requestedSerial = String(body.cardSerial || '').toUpperCase().replace(/[^0-9A-Z .$/+%-]/g, '').slice(0, 40);
    const serial = requestedSerial || currentSerial;
    const currentStatus = profile.expires && profile.expires < new Date().toISOString().slice(0, 10) ? 'Expired' : profile.status;
    if (profile.sample || currentStatus !== 'Approved' || !currentSerial) return json({error: 'Approve the vendor and issue a current card before recording card handling.'}, 409);
    if (serial !== currentSerial) return json({error: 'The card serial must match the current issued card.'}, 409);
    const at = stamp();
    await db.prepare('INSERT INTO permit_documents(id,vendor_id,kind,card_serial,permit_expires,note,actor,actor_id,created_at) VALUES(?,?,?,?,?,?,?,?,?)')
      .bind(crypto.randomUUID(), vendorId, kind, serial, '', note, account.name, account.id, at).run();
    await writeAudit(db, 'permit-document', vendorId, kind, null, {cardSerial: serial, note}, account.name, at, account.id);
    return json({ok: true});
  } catch (error) {
    console.error(error);
    return json({error: 'The card event could not be recorded.'}, 503);
  }
}

import {database} from '../../../lib/server';
import {ensureAccounts, passwordPending, sessionUser} from '../../../lib/accounts';
import {noticePdf} from '../../../lib/notices';

export async function GET(req: Request) {
  try {
    const db = database();
    await ensureAccounts(db);
    const account = await sessionUser(db, req);
    if (!account) return Response.json({error: 'Sign in required.'}, {status: 401});
    if (passwordPending(account)) return Response.json({error: 'Change your password before continuing.'}, {status: 403});
    if (account.role === 'field') return Response.json({error: 'Payment receipts are restricted to office staff.'}, {status: 403, headers: {'Cache-Control': 'no-store'}});
    const eventId = new URL(req.url).searchParams.get('eventId') || '';
    const event = await db.prepare('SELECT id,vendor_id,kind,amount,note,created_at,actor,receipt_no,pay_method,pay_ref,cashier,reversal_of FROM events WHERE id=?').bind(eventId).first<any>();
    if (!event || event.kind !== 'Payment') return Response.json({error: 'Payment receipt not found.'}, {status: 404});
    const reversal = await db.prepare("SELECT id,created_at,note,actor FROM events WHERE kind='Reversal' AND reversal_of=?").bind(event.id).first<any>();
    const row = await db.prepare('SELECT payload FROM vendors WHERE id=?').bind(event.vendor_id).first<{payload: string}>();
    const vendor = row ? JSON.parse(row.payload) : {business: event.vendor_id, name: ''};
    const amount = (event.amount / 100).toLocaleString('en-ZA', {style: 'currency', currency: 'ZAR'});
    const lines = [
      'SOL PLAATJE MUNICIPALITY',
      'Local Economic Development',
      reversal ? 'REVERSED payment receipt' : 'Payment receipt',
      '',
      'Receipt ' + (event.receipt_no || 'not numbered'),
      'Vendor ' + (vendor.business || event.vendor_id),
      'Trader ' + (vendor.name || ''),
      'Vendor ID ' + event.vendor_id,
      'Amount ' + amount,
      'Method ' + (event.pay_method || 'Not recorded'),
      'Reference ' + (event.pay_ref || 'Not recorded'),
      'Cashier ' + (event.cashier || event.actor),
      'Recorded ' + event.created_at,
      '',
      event.note,
    ];
    if (reversal) {
      lines.push('', 'REVERSED', 'Reversal reference ' + reversal.id, 'Reversed on ' + reversal.created_at + ' by ' + reversal.actor, reversal.note || '');
    }
    lines.push('', 'This receipt records a ledger entry. It is not a bank confirmation.');
    if (reversal) lines.push('This payment has been reversed and must not be treated as an outstanding credit to the trader.');
    const pdf = noticePdf(lines);
    return new Response(pdf, {headers: {'Content-Type': 'application/pdf', 'Content-Disposition': `attachment; filename="receipt-${eventId.slice(0, 8)}.pdf"`, 'Cache-Control': 'private, no-store'}});
  } catch (error) {
    console.error(error);
    return Response.json({error: 'The receipt could not be prepared.'}, {status: 503});
  }
}

import { bucket, database, noticeWebhook } from '../../../lib/server';
