interface SqlStatement {
  bind(...args: unknown[]): SqlStatement;
  first<T = any>(): Promise<T | null>;
  all<T = any>(): Promise<{results: T[]}>;
  run(): Promise<unknown>;
}

interface Sql {
  prepare(query: string): SqlStatement;
  batch(statements: SqlStatement[]): Promise<unknown>;
}

